head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > selectedCellOverColor]<br/>마우스 포인터가 포커스된 Body Row 에 오버될때 포커스된 Body Cell 의 배경색으로 적용될 색상. rowMouseOver=true 이고 focusMode='cell','both' 인 경우 동작.",
    "validation" : [
        "Body Row 에 마우스 오버 시 rowMouseOverColor < selectedRowOverColor < selectedCellOverColor 순서로 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (con_ 옵션을 properties 객체로 모아 createCList 로 속성 문자열 생성, 빈값 자동 제외)
    //  - rowMouseOver 는 본 샘플 검증 전제이므로 "true" 하드코딩, 옵션으로 노출하지 않음
    //  - focusMode 는 selectedCellOverColor / selectedRowOverColor 가 모두 동작하는 "both" 하드코딩
    //  - selectedCellColor / selectedRowColor 는 포커스 상태 가시화를 위해 기본 색을 부여
    //  - rowMouseOverColor / selectedRowOverColor / selectedCellOverColor 세 색을 다르게 설정하여
    //    오버 시 우선순위(rowMouseOverColor < selectedRowOverColor < selectedCellOverColor) 입증.
    //    상위 미설정 시 하위 색으로 fallback 되는지도 확인 (일부만 설정한 케이스).
    let properties = {
        dataList             : "data:dlt_bind",
        focusMode            : "both",
        rowMouseOver         : "true",
        selectedCellColor    : "yellow",
        selectedRowColor     : "lightgreen",
        rowMouseOverColor    : con_rowMouseOverColor.getValue(),
        selectedRowOverColor : con_selectedRowOverColor.getValue(),
        selectedCellOverColor: con_selectedCellOverColor.getValue()
    };
    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onbodymouseover"]);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblMouseOver = (properties.rowMouseOverColor === '') ? '미설정' : properties.rowMouseOverColor;
    let lblRowOver = (properties.selectedRowOverColor === '') ? '미설정' : properties.selectedRowOverColor;
    let lblCellOver = (properties.selectedCellOverColor === '') ? '미설정' : properties.selectedCellOverColor;
    $c.gcm.createLabel('label="rowMouseOver=true / focusMode=both (고정) / rowMouseOverColor=' + lblMouseOver + ' / selectedRowOverColor=' + lblRowOver + ' / selectedCellOverColor=' + lblCellOver + ' 로 GridView 생성. 포커스 Cell 의 Row 오버 시 우선순위 rowMouseOverColor → selectedRowOverColor → selectedCellOverColor 순으로 적용"', '', 'label1');

    // dataList 생성 (헬퍼와 동일하게 col1~col4 컬럼 구성)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);
}



// 지정한 Body Cell 을 포커스시키는 사전상태 설정 (마우스 오버는 사용자 동작으로 수행)
//  - rowIndex/colIndex 는 par_ 콤보에서 선택
scwin.btn_setFocusedCell_onclick = function () {
    let rowIndex = parseInt(par_rowIndex.getValue(), 10);
    let colIndex = parseInt(par_colIndex.getValue(), 10);

    // DataList currentRow 정합성 유지
    dlt_bind.setRowPosition(rowIndex);
    target1.setFocusedCell(rowIndex, colIndex);

    wf_body_bottom.getObj("scwin").setReturnValue("[포커스 설정] Cell(" + rowIndex + "," + colIndex + ") 포커스. 해당 Row(우선순위 확인) 또는 다른 Row(rowMouseOverColor 확인)에 마우스를 오버하세요.");
}



// 마우스가 오버되면 자동 출력 (onbodymouseover)
//  - 우선순위 입증: focusMode='both' 환경에서 포커스 Cell 의 Row 를 오버하면
//      · 포커스 Cell        → selectedCellOverColor (최우선, 미설정 시 하위로 fallback)
//      · 동일 Row 다른 Cell → selectedRowOverColor   (미설정 시 rowMouseOverColor 로 fallback)
//  - 포커스 Row 가 아닌 다른 Row 를 오버하면
//      · 해당 Row 전체       → rowMouseOverColor (기본 오버색)
scwin.target1_onbodymouseover = function (info) {
    let fRowIndex = target1.getFocusedRowIndex();
    let fColIndex = target1.getFocusedColumnIndex();
    let overRow = info.rowIndex;

    // 포커스된 Cell 이 없으면 (사전상태 미설정) 안내만 출력
    if (fRowIndex === null || fRowIndex === undefined || fRowIndex < 0 ||
        fColIndex === null || fColIndex === undefined || fColIndex < 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("[안내] 먼저 setFocusedCell 로 포커스 Cell 을 설정하세요.");
        return;
    }

    if (overRow === fRowIndex) {
        // 포커스된 Cell 의 Row 오버 → 우선순위 입증 (cell 최우선, 동일 row 다른 cell 차순위)
        let focusedTd = document.querySelector("td[id*='mf_target1_cell_" + fRowIndex + "_" + fColIndex + "']");
        let focusedColor = focusedTd ? window.getComputedStyle(focusedTd).backgroundColor : "(cell 없음)";

        let otherCol = (fColIndex === 0) ? 1 : 0;
        let otherTd = document.querySelector("td[id*='mf_target1_cell_" + fRowIndex + "_" + otherCol + "']");
        let otherColor = otherTd ? window.getComputedStyle(otherTd).backgroundColor : "(cell 없음)";

        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbodymouseover (포커스 Row " + fRowIndex + " 오버)=====");
        wf_body_bottom.getObj("scwin").setReturnValue("[포커스 Cell(" + fRowIndex + "," + fColIndex + ") 배경색 → selectedCellOverColor 우선] " + focusedColor);
        wf_body_bottom.getObj("scwin").setReturnValue("[동일 Row 다른 Cell(" + fRowIndex + "," + otherCol + ") 배경색 → selectedRowOverColor 적용] " + otherColor);
    } else {
        // 포커스 Row 가 아닌 다른 Row 오버 → rowMouseOverColor (기본 오버색)
        let plainTd = document.querySelector("td[id*='mf_target1_cell_" + overRow + "_0']");
        let plainColor = plainTd ? window.getComputedStyle(plainTd).backgroundColor : "(cell 없음)";

        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbodymouseover (비포커스 Row " + overRow + " 오버)=====");
        wf_body_bottom.getObj("scwin").setReturnValue("[비포커스 Row(" + overRow + ") Cell 배경색 → rowMouseOverColor 적용] " + plainColor);
    }
}
